WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_pf_bd_bundle'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '捆绑销售', 'kp-pf-bd-bundle', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "捆绑销售"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心定义：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "“买三送一”、“10元3个”。本质上是一种变相打折。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "“商品单价 5 元，现搞促销‘买三送一’。如果小明需要 10 件商品，最少花多少钱？”"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心推导：打包法"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "买三送一，说明你只要花 3 个商品的钱（15元），就能拿到 4 个商品！"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "所以我们把 4 个商品看成一个“大礼包”，这个礼包的标价是 15 元。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[看清促销规则: 花多少钱, 拿几个货?] --> B[把拿到的总数作为一个大礼包, 算出大礼包的实际价格]\nB --> C[用顾客需要的总件数 ÷ 礼包内的件数 = 需要买几个大礼包 ... 余数]\nC --> D[余数部分, 只能按单价硬买]\nD --> E[总花费 = 礼包数 × 礼包价 + 余数 × 单价]"}}]}$$ AS jsonb), NULL, '捆绑销售的核心考点与实战推导。', category_node.id, CAST('["数量关系", "经济利润", "捆绑销售"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_pf_bd_bundle", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
